{"content":"const fs = require('fs');

function fail(msg) {
  process.stderr.write(`Error: ${msg}\n`);
  process.exit(1);
}

function readVarInt(buf, offset) {
  if (offset >= buf.length) fail('unexpected end of data while reading VarInt');
  const first = buf[offset];
  if (first < 0xfd) {
    return { value: first, size: 1 };
  } else if (first === 0xfd) {
    if (offset + 3 > buf.length) fail('unexpected end of data while reading VarInt (0xfd)');
    const value = buf.readUInt16LE(offset + 1);
    return { value, size: 3 };
  } else if (first === 0xfe) {
    if (offset + 5 > buf.length) fail('unexpected end of data while reading VarInt (0xfe)');
    const value = buf.readUInt32LE(offset + 1);
    return { value, size: 5 };
  } else {
    // 0xff
    if (offset + 9 > buf.length) fail('unexpected end of data while reading VarInt (0xff)');
    const big = buf.readBigUInt64LE(offset + 1);
    if (big > BigInt(Number.MAX_SAFE_INTEGER)) {
      fail('VarInt value exceeds max safe integer');
    }
    return { value: Number(big), size: 9 };
  }
}

function main() {
  const filePath = process.argv[2];
  if (!filePath) {
    fail('missing file path argument. Usage: node parse_tx.js <path_to_hex_file>');
  }

  let raw;
  try {
    raw = fs.readFileSync(filePath, 'utf8');
  } catch (e) {
    fail(`cannot read file: ${e.message}`);
  }

  // Strip whitespace (spaces, newlines, tabs, etc.)
  const hex = raw.replace(/\s+/g, '');

  if (hex.length === 0) {
    fail('empty hex string');
  }
  if (hex.length % 2 !== 0) {
    fail('hex string has odd length');
  }
  if (!/^[0-9a-fA-F]*$/.test(hex)) {
    fail('hex string contains non-hex characters');
  }

  let buf;
  try {
    buf = Buffer.from(hex, 'hex');
  } catch (e) {
    fail(`invalid hex string: ${e.message}`);
  }
  if (buf.length === 0) {
    fail('empty transaction data');
  }

  let offset = 0;

  function need(n, what) {
    if (offset + n > buf.length) {
      fail(`unexpected end of data while reading ${what}`);
    }
  }

  // Version (4 bytes LE)
  need(4, 'version');
  const version = buf.readUInt32LE(offset);
  offset += 4;

  // Input count (VarInt)
  const inCount = readVarInt(buf, offset);
  offset += inCount.size;
  const inputCount = inCount.value;

  const inputs = [];
  for (let i = 0; i < inputCount; i++) {
    // txid (32 bytes, LE -> reversed for display)
    need(32, `input ${i} txid`);
    const txidBytes = buf.subarray(offset, offset + 32);
    const txid = Buffer.from(txidBytes).reverse().toString('hex').toLowerCase();
    offset += 32;

    // vout (4 bytes LE)
    need(4, `input ${i} vout`);
    const vout = buf.readUInt32LE(offset);
    offset += 4;

    // scriptsig length (VarInt)
    const slen = readVarInt(buf, offset);
    offset += slen.size;

    // scriptsig
    need(slen.value, `input ${i} scriptsig`);
    const scriptsig = buf.subarray(offset, offset + slen.value).toString('hex').toLowerCase();
    offset += slen.value;

    // sequence (4 bytes LE)
    need(4, `input ${i} sequence`);
    const sequence = buf.readUInt32LE(offset);
    offset += 4;

    inputs.push({ txid, vout, scriptsig, sequence });
  }

  // Output count (VarInt)
  const outCount = readVarInt(buf, offset);
  offset += outCount.size;
  const outputCount = outCount.value;

  const outputs = [];
  for (let i = 0; i < outputCount; i++) {
    // value (8 bytes LE)
    need(8, `output ${i} value`);
    const big = buf.readBigUInt64LE(offset);
    offset += 8;
    const value = Number(big);
    if (!Number.isSafeInteger(value)) {
      // Still emit as number would lose precision; but spec requires integer.
      // Only fail if it truly exceeds safe range to avoid silent corruption? 
      // Instead, keep behavior deterministic: fail with clear error.
      // However typical amounts fit safely; guard against precision loss.
      fail(`output ${i} value exceeds max safe integer`);
    }

    // scriptpubkey length (VarInt)
    const plen = readVarInt(buf, offset);
    offset += plen.size;

    // scriptpubkey
    need(plen.value, `output ${i} scriptpubkey`);
    const scriptpubkey = buf.subarray(offset, offset + plen.value).toString('hex').toLowerCase();
    offset += plen.value;

    outputs.push({ value, scriptpubkey });
  }

  // Locktime (4 bytes LE)
  need(4, 'locktime');
  const locktime = buf.readUInt32LE(offset);
  offset += 4;

  const result = {
    version,
    input_count: inputCount,
    inputs,
    output_count: outputCount,
    outputs,
    locktime,
  };

  process.stdout.write(JSON.stringify(result) + '\n');
}

main();
